#[test]
fn native_pushes_take_over_the_restored_commits() {
    let target = Db::new(&[101], &[11], &[], &[21, 22], &[S1, S2, T2])
        .texts(&[S1.id, S2.id, T2.id])
        .ecf(&[S1.id, S2.id]);
    let source = Db::new(&[101], &[11], &[], &[21, 22], &[T2, N1, N2, N3]);
    let Some(rs) = both(
        &Case::new("takeover")
            .db("tgt", target)
            .db("src", source)
            .env("GHA2DB_RECONCILE_DBS", "{db:src}"),
    ) else {
        return;
    };
    assert_eq!(rs.code(), Some(0));
    assert_eq!(
        rs.lines(),
        [
            header(
                "explicit (GHA2DB_RECONCILE_DBS)",
                "<dbs>_src",
                "90 days",
                "native, orphan",
                false
            ),
            NO_FILTER.to_string(),
            format!("{P}: scope 1 repo(s) (target 1, source 1)"),
            // Same counts on day -6 (2 vs 2) but different id sums.
            format!("{P}: buckets: source 2, target 2, differing 2"),
            format!("{P}: events: source-only 3 (native 3, orphan 0, artificial 0), target-only 2"),
            format!("{P}: table gha_events: rows 3, inserted 3"),
            format!("{P}: table gha_payloads: rows 3, inserted 3"),
            format!("{P}: table gha_commits: rows 5, inserted 5"),
            format!("{P}: table gha_commits_roles: rows 10, inserted 10"),
            format!("{P}: table gha_repos: rows 1, inserted 0"),
            format!("{P}: table gha_orgs: rows 1, inserted 0"),
            format!("{P}: table gha_actors: rows 2, inserted 0"),
            format!("{P}: taken over 2 commit(s) from 2 restored push event(s), removed 1 emptied restored event(s)"),
            format!("{P}: copied 3 event(s), inserted 21 row(s), postprocess 4 event id(s)"),
            "targeted postprocess executed for 4 restored event id(s)".to_string(),
            "reconcile_dbs: <dbs>_tgt: 1 source(s), copied 3 event(s), inserted 21 row(s), filtered out 0 event(s), skipped 0 orphan event(s), taken over 2 commit(s)".to_string(),
            "Time: <duration>".to_string(),
        ]
    );
    // S1 is gone (with its payload, text and files), S2 kept Z.
    assert_eq!(rs.event_ids(), [S2.id, N1.id, N2.id, N3.id, T2.id]);
    assert_eq!(
        rs.commits(),
        [
            // V: copied under N1 and N2 - the lowest event id is distinct.
            (SHA_V.to_string(), N1.id, true),
            (SHA_V.to_string(), N2.id, false),
            // W: T2 had it before - the copied row is not distinct.
            (SHA_W.to_string(), N3.id, false),
            (SHA_W.to_string(), T2.id, true),
            // X and Y: taken over from S1 and S2.
            (SHA_X.to_string(), N1.id, true),
            (SHA_Y.to_string(), N2.id, true),
            (SHA_Z.to_string(), S2.id, true),
        ]
    );
    assert_eq!(
        rs.query("select event_id from gha_commits_roles group by event_id order by event_id"),
        [S2.id, N1.id, N2.id, N3.id, T2.id].map(|id| id.to_string())
    );
    assert_eq!(
        rs.query(
            "select event_id || ':' || sha from gha_events_commits_files order by event_id, sha"
        ),
        [format!("{}:{SHA_Y}", S2.id), format!("{}:{SHA_Z}", S2.id)]
    );
    assert_eq!(
        rs.query("select event_id from gha_payloads order by event_id"),
        [S2.id, N1.id, N2.id, N3.id, T2.id].map(|id| id.to_string())
    );
    // Texts: S1's row is gone, S2's was rebuilt from its remaining commit,
    // T2's untouched.
    assert_eq!(
        rs.query("select event_id || ':' || body from gha_texts order by event_id, body"),
        [
            format!("{}:commit 9999999 of {}", S2.id, S2.id),
            format!("{}:commit 5555555 of {}", N1.id, N1.id),
            format!("{}:commit 7777777 of {}", N1.id, N1.id),
            format!("{}:commit 5555555 of {}", N2.id, N2.id),
            format!("{}:commit 8888888 of {}", N2.id, N2.id),
            format!("{}:commit 6666666 of {}", N3.id, N3.id),
            format!("{}:text of {}", T2.id, T2.id),
        ]
    );
}

