/// Project mode: `alpha` and `zeta` live in the target database (`alpha`
/// sharing into `src`, `zeta` into the missing `ghost`), `omega` is a
/// disabled project of the same database, `beta` has no shared database.
const PROJECT_YAML: &str = r#"---
projects:
  zeta:
    name: Zeta
    psql_db: {db:tgt}
    shared_db: {db:ghost}
    order: 2
  alpha:
    name: Alpha
    psql_db: {db:tgt}
    shared_db: " {db:src} "
    order: 1
  omega:
    name: Omega
    psql_db: {db:tgt}
    shared_db: {db:ghost}
    disabled: true
    order: 0
  beta:
    name: Beta
    psql_db: {db:beta}
    order: 3
  other:
    name: Other
    psql_db: {db:src}
    shared_db: elsewhere
    order: 4
"#;

fn project_case(name: &'static str) -> Case {
    Case::new(name)
        .db("tgt", main_target())
        .db("src", main_source())
        .db("beta", Db::new(&[101], &[11], &[], &[21], &[E1]))
        .missing("ghost")
        .yaml(PROJECT_YAML)
}

#[test]
fn project_mode_uses_the_given_project() {
    let Some(rs) = both(&project_case("project").env("GHA2DB_PROJECT", "alpha")) else {
        return;
    };
    assert_eq!(rs.code(), Some(0));
    assert_eq!(
        rs.lines()[0],
        header(
            "project (project 'alpha' shared_db '<dbs>_src' in ./projects.yaml)",
            "<dbs>_src",
            "90 days",
            "native, orphan",
            false
        )
    );
    assert!(rs.has_line(
        "reconcile_dbs: <dbs>_tgt: 1 source(s), copied 5 event(s), inserted 23 row(s), filtered out 0 event(s), skipped 1 orphan event(s), taken over 0 commit(s)"
    ));
    assert_eq!(
        rs.event_ids(),
        [O2.id, T1.id, E1.id, E2.id, E3.id, E6.id, E7.id]
    );
}

